let cdqPdfOpenStateV2289=null;

function cdqPdfShowSystemChooserV2289(state,rec){
  const old=document.getElementById('cdqPdfOpenChooserV2289');
  if(old)old.remove();

  const o=cdqV19CreateModal(
    'cdqPdfOpenChooserV2289',
    'Ouvrir — '+String((rec&&rec.nom)||state.name||'Rapport PDF'),
    'cdq-pdf-open-chooser-v2289'
  );
  const body=o.querySelector('.cdq-v19-body');
  body.innerHTML='';

  cdqDocumentText(
    body,
    'Compte Google : '+String(state.email||'sélectionné')+
    '. Touchez « Ouvrir avec… » pour choisir une application PDF installée.'
  );

  const open=cdqDocumentButton(body,'Ouvrir avec…',async function(){
    if(!rec||!(rec.blob instanceof Blob)||rec.blob.type!=='application/pdf'||rec.blob.size<5){
      afficherMessage('Le PDF prêt est invalide.',false);
      return;
    }

    const safe=String(rec.nom||state.name||'Rapport.pdf')
      .replace(/[\\/\x00-\x1f]/g,'_')
      .slice(0,180);
    const file=new File(
      [rec.blob],
      /\.pdf$/i.test(safe)?safe:safe+'.pdf',
      {type:'application/pdf'}
    );
    const payload={files:[file],title:file.name};

    if(!(navigator.share&&(!navigator.canShare||navigator.canShare(payload)))){
      afficherMessage('Le sélecteur Android des applications PDF n’est pas disponible.',false);
      return;
    }

    try{
      open.disabled=true;
      open.textContent='Ouverture…';
      await navigator.share(payload);
      cdqPdfOpenStateV2289=null;
      o.style.display='none';
    }catch(e){
      open.disabled=false;
      open.textContent='Ouvrir avec…';
      if(!e||e.name!=='AbortError'){
        afficherMessage('Android n’a pas pu afficher les applications PDF. Réessayez.',false);
      }
    }
  });

  cdqDocumentButton(body,'Annuler',function(){
    cdqPdfOpenStateV2289=null;
    o.style.display='none';
  });

  o.style.display='flex';
}

async function cdqPdfPrepareAfterAccountV2289(state){
  try{
    afficherMessage('Chargement du PDF…',true);
    const rec=await cdqLoadPdfRecord(state.id);

    if(!rec||!(rec.blob instanceof Blob)||rec.blob.type!=='application/pdf'||rec.blob.size<5){
      throw new Error('Le PDF reçu est invalide.');
    }

    if(state.reader==='cdq'){
      cdqPdfOpenStateV2289=null;
      await cdqOpenPdfInternal(state.id,rec);
      return;
    }

    cdqPdfShowSystemChooserV2289(state,rec);
  }catch(e){
    cdqPdfOpenStateV2289=null;
    afficherErreur(e);
  }
}

function cdqPdfAskAccountV2289(id){
  const meta=cdqDocumentMeta(id)||{};
  const state={
    requestId:'pdf-'+crypto.randomUUID(),
    id:String(id),
    name:String(meta.nom||'Rapport.pdf'),
    reader:typeof cdqPdfReaderPreference==='function'?cdqPdfReaderPreference():'ask',
    challengeId:'',
    email:''
  };

  cdqPdfOpenStateV2289=state;
  afficherMessage('Choisissez le compte Google pour ouvrir le PDF.',true);

  cdqApiRun()
    .withSuccessHandler(function(defi){
      const current=cdqPdfOpenStateV2289;
      if(!current||current.requestId!==state.requestId)return;

      if(!defi||!defi.challengeId||!defi.nonce||!defi.clientId){
        cdqPdfOpenStateV2289=null;
        afficherMessage('Impossible de préparer le choix du compte Google.',false);
        return;
      }

      current.challengeId=String(defi.challengeId);

      cdqPostToPwa({
        type:'CDQ_PDF_ACCOUNT_PROMPT_V2289',
        requestId:current.requestId,
        challengeId:String(defi.challengeId),
        nonce:String(defi.nonce),
        clientId:String(defi.clientId),
        expiresAt:Number(defi.expiresAt)||0,
        name:current.name
      });
    })
    .withFailureHandler(function(e){
      cdqPdfOpenStateV2289=null;
      afficherMessage(e&&e.message?e.message:String(e),false);
    })
    .creerDefiConnexionGoogleCDQ();
}

window.addEventListener('message',function(e){
  if(!cdqFromPwa(e))return;
  const d=e.data||{};
  const state=cdqPdfOpenStateV2289;
  if(!state)return;

  if(d.type==='CDQ_PDF_ACCOUNT_CANCEL_V2289' &&
     String(d.requestId||'')===state.requestId){
    cdqPdfOpenStateV2289=null;
    return;
  }

  if(d.type!=='CDQ_PDF_ACCOUNT_CREDENTIAL_V2289')return;
  if(String(d.requestId||'')!==state.requestId)return;
  if(String(d.challengeId||'')!==state.challengeId)return;
  if(!d.credential)return;

  const requestId=state.requestId;

  cdqApiRun()
    .withSuccessHandler(function(resultat){
      const current=cdqPdfOpenStateV2289;
      if(!current||current.requestId!==requestId)return;

      if(!resultat||!resultat.ok){
        cdqPdfOpenStateV2289=null;
        afficherMessage('Google n’a pas confirmé ce compte.',false);
        return;
      }

      current.email=String(resultat.email||'');
      Promise.resolve(cdqPdfPrepareAfterAccountV2289(current)).catch(function(err){
        cdqPdfOpenStateV2289=null;
        afficherErreur(err);
      });
    })
    .withFailureHandler(function(err){
      cdqPdfOpenStateV2289=null;
      afficherMessage(err&&err.message?err.message:String(err),false);
    })
    .verifierJetonGoogleCDQ(String(d.credential),String(d.challengeId));
});

const cdqV19OldModify=window.modifierFichier;
window.modifierFichier=function(id){
  const meta=cdqDocumentMeta(id);

  if(meta&&meta.type==='GOOGLE_SHEETS'){
    cdqV19OpenOfflineSheet(id);
    return;
  }

  if(meta&&meta.type==='PDF'){
    if(navigator.onLine!==false && /Android/i.test(navigator.userAgent||'')){
      cdqPdfAskAccountV2289(id);
      return;
    }

    if(navigator.onLine!==false)return cdqV19OldModify(id);
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  if(!navigator.onLine){
    afficherMessage('Ouvrez ce fichier dans son application après l’avoir enregistré sur le téléphone.',false);
    return;
  }

  return cdqV19OldModify(id);
};
